"""Local branch marketing workspace."""
from fastapi import APIRouter, Response
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["CRM local marketing workspace"], include_in_schema=False)
_HEADERS = {"Cache-Control":"no-store","Content-Security-Policy":"default-src 'self'; script-src 'self'; style-src 'unsafe-inline'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'","Referrer-Policy":"no-referrer","X-Content-Type-Options":"nosniff"}
_PAGE = """<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>شعب و بازاریابی محلی | فانل CRM</title><style>
:root{font-family:Tahoma,Arial,sans-serif;color:#172c42;background:#f4f7fb}*{box-sizing:border-box}body{margin:0}.app{min-height:100vh;display:grid;grid-template-columns:230px 1fr}aside{background:#fff;border-left:1px solid #e3e9f0;padding:20px 14px;position:sticky;top:0;height:100vh}.brand{font-size:19px;font-weight:bold;padding:0 10px 24px}.brand b{color:#158b91}nav{display:grid;gap:5px}.nav{display:block;padding:11px;border-radius:9px;color:#54677a;text-decoration:none;font-size:12px}.nav.active{background:#eaf4f7;color:#125779}.main{min-width:0;padding:24px clamp(16px,3vw,42px) 48px}.top,.filters{display:flex;gap:10px;align-items:end;flex-wrap:wrap}.top{margin-bottom:20px}.field{display:grid;gap:6px;font-size:11px;color:#778697}select,input{font:inherit;border:1px solid #dfe6ed;background:#fff;border-radius:9px;padding:10px;min-width:150px}h1{font-size:25px;margin:0 0 8px}.sub{color:#718092;font-size:13px;line-height:1.8;margin:0 0 16px}.toolbar{display:flex;justify-content:space-between;align-items:end;gap:15px;margin-bottom:14px}.status{min-height:20px;color:#718092;font-size:12px}.error{color:#a74137}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin:14px 0}.card{background:#fff;border:1px solid #e5eaf0;border-radius:12px;padding:16px;box-shadow:0 4px 14px #1c334408;min-width:0}.label{color:#657487;font-size:11px}.value{font-size:22px;font-weight:bold;color:#1a334c;margin:9px 0 3px}.meta{font-size:10px;color:#8290a0;line-height:1.7}.grid{display:grid;grid-template-columns:1.4fr 1fr;gap:14px}.heading{display:flex;justify-content:space-between;align-items:center;margin:0 0 12px}.heading h2{font-size:15px;margin:0}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:660px;font-size:11px}th,td{text-align:right;padding:10px 8px;border-bottom:1px solid #eef1f4}th{background:#f8fafc;color:#728092}td{color:#33465c}.bars,.events{display:grid;gap:9px}.barrow{display:grid;grid-template-columns:100px 1fr 56px;gap:8px;align-items:center;font-size:11px}.track{height:9px;background:#edf2f6;border-radius:9px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,#24b5a5,#17658e);min-width:2px}.event{padding:10px;border:1px solid #e8edf2;border-radius:9px;font-size:11px}.event strong{display:block;margin-bottom:5px;color:#304b60}.note,.empty{font-size:11px;line-height:1.8;color:#7b8998}.empty{text-align:center;padding:14px;border:1px dashed #d4dde6;border-radius:9px}@media(max-width:900px){.grid{grid-template-columns:1fr}}@media(max-width:760px){.app{display:block}aside{position:relative;height:auto;border:0;border-bottom:1px solid #e3e9f0;padding:12px}.brand{padding-bottom:8px}nav{display:flex;overflow:auto}.nav{white-space:nowrap}.toolbar{display:block}.filters{margin-top:12px}.kpis{grid-template-columns:repeat(2,1fr)}}@media(max-width:480px){.main{padding:15px 12px}.top{display:grid}.field,select,input{width:100%;min-width:0}.kpis{gap:7px}.card{padding:12px}.value{font-size:18px}}</style><script src="/assets/crm-local-marketing.js" defer></script></head><body><div class="app"><aside><div class="brand">فانل <b>CRM</b></div><nav aria-label="ماژول‌های CRM"><a class="nav" href="/workspace/marketing-manager">میزکار مدیر بازاریابی</a><a class="nav" href="/workspace/crm-campaigns">کمپین و محتوا</a><a class="nav active" href="/workspace/crm-local-marketing" aria-current="page">شعب و بازاریابی محلی</a><a class="nav" href="/workspace/crm-analytics">تحلیل و هوش تجاری</a><a class="nav" href="/workspace/crm-learning">یادگیری و بهبود مستمر</a></nav></aside><main class="main"><div class="top"><label class="field">فضای کاری<select id="workspace"><option value="">در حال دریافت…</option></select></label></div><h1>شعب و بازاریابی محلی</h1><p class="sub">عملکرد کمپین‌ها و تقویم اجرا را در واحدهای سازمانی مجاز مرور و مقایسه کنید.</p><div class="toolbar"><div class="filters"><label class="field">از تاریخ<input id="start" type="date"></label><label class="field">تا تاریخ<input id="end" type="date"></label><label class="field">مقایسهٔ شعب<select id="units" multiple size="3" aria-label="انتخاب واحدها برای مقایسه"></select></label></div><button id="refresh" type="button">به‌روزرسانی</button></div><p id="status" class="status" role="status" aria-live="polite"></p><section class="kpis"><article class="card"><div class="label">واحدهای در دسترس</div><div id="unit-count" class="value">—</div><div class="meta">طبق مجوزهای کاربر</div></article><article class="card"><div class="label">کمپین‌های مقایسه</div><div id="campaign-count" class="value">—</div><div class="meta">در بازهٔ انتخابی</div></article><article class="card"><div class="label">تبدیل‌های گزارش‌شده</div><div id="conversion-count" class="value">—</div><div class="meta">مجموع واحدهای موفق بارگذاری</div></article><article class="card"><div class="label">واحدهای دارای خطا</div><div id="error-count" class="value">—</div><div class="meta">برای جلوگیری از برداشت ناقص</div></article></section><div class="grid"><section class="card"><div class="heading"><h2>مقایسهٔ عملکرد شعب</h2><span class="meta">هزینه و درآمد به تفکیک ارز</span></div><div id="comparison" class="table-wrap"><div class="empty">واحدها را انتخاب کنید.</div></div><p class="note">شاخص‌های مالی بین ارزهای متفاوت جمع نمی‌شوند. نرخ‌ها فقط در صورت وجود دادهٔ ثبت‌شده نمایش داده می‌شوند.</p></section><section class="card"><div class="heading"><h2>تقویم محلی</h2><span class="meta">کمپین‌ها و کارهای مجاز</span></div><div id="calendar" class="events"><div class="empty">پس از انتخاب واحد نمایش داده می‌شود.</div></div></section><section class="card"><div class="heading"><h2>ترکیب کانال برای شعبهٔ منتخب</h2></div><div id="channels" class="bars"><div class="empty">گزارش کانال‌ها نمایش داده می‌شود.</div></div></section></div><p class="note">هر گزارش برای واحد انتخاب‌شده از APIای بارگذاری می‌شود که مجوز آن را مستقلاً کنترل می‌کند. اطلاعات ناموفق یا ناقص به‌عنوان خطا مشخص می‌شود.</p></main></div></body></html>"""
_SCRIPT = """(()=>{
const $=id=>document.getElementById(id),ws=$("workspace"),units=$("units"),fmt=new Intl.NumberFormat("fa-IR",{maximumFractionDigits:2});let orgs=[],reports=[];
function say(s,e=false){$("status").textContent=s;$("status").classList.toggle("error",e)}function node(t,v,c=""){const n=document.createElement(t);n.textContent=String(v??"—");if(c)n.className=c;return n}
async function api(path){const r=await fetch(path,{credentials:"same-origin",headers:{Accept:"application/json","X-Workspace-ID":ws.value}});let d={};try{d=await r.json()}catch(_){}if(!r.ok)throw Error(typeof d.detail==="string"?d.detail:"خطا در دریافت داده");return d}
function money(m){return Object.entries(m||{}).map(([c,v])=>fmt.format(Number(v))+" "+c).join("، ")||"—"}
function draw(){const good=reports.filter(x=>x.data),failed=reports.length-good.length;$("unit-count").textContent=fmt.format(orgs.length);$("campaign-count").textContent=fmt.format(good.reduce((a,x)=>a+(x.data.totals.campaign_count||0),0));$("conversion-count").textContent=fmt.format(good.reduce((a,x)=>a+(x.data.totals.totals.conversions||0),0));$("error-count").textContent=fmt.format(failed);const tbl=document.createElement("table"),hd=document.createElement("tr");["واحد","کمپین","کلیک","سرنخ","تبدیل","نرخ تبدیل به کلیک","هزینهٔ واقعی","درآمد منتسب"].forEach(x=>hd.append(node("th",x)));const th=document.createElement("thead");th.append(hd);tbl.append(th);const body=document.createElement("tbody");for(const r of reports){const tr=document.createElement("tr");if(!r.data){tr.append(node("td",r.name),node("td","دریافت ناموفق"));for(let i=0;i<6;i++)tr.append(node("td","—"))}else{const t=r.data.totals;[r.name,t.campaign_count,t.totals.clicks,t.totals.leads,t.totals.conversions,t.conversion_rate_per_click_percent==null?"—":fmt.format(t.conversion_rate_per_click_percent)+"٪",money(t.actual_spend_by_currency),money(t.attributed_revenue_by_currency)].forEach(x=>tr.append(node("td",x)))}body.append(tr)}tbl.append(body);$("comparison").replaceChildren(tbl);const ch=$("channels");ch.replaceChildren();const first=good[0]?.data;if(!first)ch.append(node("div","دادهٔ کانال در دسترس نیست","empty"));else{const max=Math.max(1,...first.groups.map(g=>g.metrics.totals.conversions||0));for(const g of first.groups){const row=document.createElement("div");row.className="barrow";row.append(node("span",g.key));const tr=document.createElement("div");tr.className="track";const f=document.createElement("div");f.className="fill";f.style.width=Math.max(2,100*(g.metrics.totals.conversions||0)/max)+"%";tr.append(f);row.append(tr,node("span",fmt.format(g.metrics.totals.conversions||0)));ch.append(row)}}}
async function load(){if(!ws.value)return;const ids=[...units.selectedOptions].map(o=>o.value);if(!ids.length){reports=[];draw();$("comparison").replaceChildren(node("div","یک یا چند واحد را برای مقایسه انتخاب کنید.","empty"));return}say("در حال بارگذاری گزارش شعب و تقویم…");const start=$("start").value,end=$("end").value;reports=await Promise.all(ids.map(async id=>{const org=orgs.find(x=>x.id===id),q=new URLSearchParams({period_start:start,period_end:end,organization_unit_id:id,grouped_by:"channel",sort_by:"conversions",limit:"100"});try{return{name:org?.name||id,data:await api("/api/v1/crm/analytics/campaign-performance/portfolio?"+q)}}catch(e){return{name:org?.name||id,error:e.message}}}));draw();const q=new URLSearchParams({period_start:start,period_end:end,organization_unit_id:ids[0],limit:"100"});try{const d=await api("/api/v1/crm/marketing-calendar/events?"+q),box=$("calendar");box.replaceChildren();if(!d.events.length)box.append(node("div","در این بازه رویدادی ثبت نشده است.","empty"));for(const e of d.events){const item=document.createElement("article");item.className="event";item.append(node("strong",e.title),node("span",e.start_date+" تا "+e.end_date+" · "+(e.kind==="campaign"?"کمپین":"کار")+" · "+e.status));box.append(item)}if(d.schedule_conflicts?.length)box.prepend(node("div",fmt.format(d.schedule_conflicts.length)+" هم‌پوشانی زمان‌بندی برای بررسی","event"))}catch(e){$("calendar").replaceChildren(node("div","تقویم بارگذاری نشد: "+e.message,"empty"))}const n=reports.filter(x=>x.error).length;say(n?"گزارش بارگذاری شد؛ "+fmt.format(n)+" واحد خطا دارد و در جدول مشخص شده.":"گزارش شعب و تقویم به‌روز شد.",false)}
async function init(){try{const w=await api("/api/v1/system/workspaces");ws.replaceChildren(...w.map(x=>{const o=document.createElement("option");o.value=x.id;o.textContent=x.name;return o}));if(!w.length)throw Error("فضای کاری مجازی برای این کاربر یافت نشد");ws.value=w[0].id;orgs=await api("/api/v1/system/organization-units");units.replaceChildren(...orgs.map(x=>{const o=document.createElement("option");o.value=x.id;o.textContent=x.name+" · "+x.unit_type;o.selected=true;return o}));const now=new Date(),from=new Date(now);from.setDate(from.getDate()-29);$("start").value=from.toISOString().slice(0,10);$("end").value=now.toISOString().slice(0,10);await load()}catch(e){say("داده‌ها بارگذاری نشد: "+e.message,true)}}
$("refresh").addEventListener("click",load);init();
})();"""
@router.get("/workspace/crm-local-marketing", response_class=HTMLResponse)
async def local_marketing_workspace() -> HTMLResponse:
    return HTMLResponse(_PAGE, headers=_HEADERS)

@router.get("/assets/crm-local-marketing.js")
async def local_marketing_script() -> Response:
    return Response(_SCRIPT, media_type="application/javascript", headers=_HEADERS)
